        Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
            years.take(8).forEach { year -> FilterChip(selected = year == selected, onClick = { onSelect(year) }, label = { Text(year.toString()) }) }
        }
    }
