    val normalized = code.trim().uppercase()
    if (!normalized.matches(Regex("[PBCU][0-3][0-9A-F]{3}"))) return null
    return runCatching {
        SupabaseClient.client
            .from("diagnostic_codes")
            .select(
                Columns.list(
                    "id",
                    "code",
                    "system",
                    "category",
                    "severity",
                    "title_fr",
                    "title_ar",
                    "description_fr",
                    "description_ar",
                    "causes_fr",
                    "causes_ar",
                    "diagnostic_steps_fr",
