/**
 * Deterministic, offline-safe diagnostic layer. AI may enrich the explanation,
 * but this engine keeps the core recommendation reproducible and testable.
 */
data class DiagnosticInput(
    val dtcCodes: List<String> = emptyList(),
    val symptoms: List<String> = emptyList(),
    val liveData: Map<String, Double> = emptyMap()
)

object DiagnosticEngine {
    fun analyze(input: DiagnosticInput): List<DiagnosticFinding> = input.dtcCodes
        .map { it.trim().uppercase() }
        .filter { it.matches(Regex("[PBCU][0-3][0-9A-F]{3}")) }
        .distinct()
        .map { code ->
            val (severity, causes, tests, recommendations, score) = when {
                code.startsWith("P03") -> DiagnosticResult(
                    "warning",
                    listOf("Ignition/fuel delivery", "Air intake or vacuum leak", "Engine mechanical condition"),
                    listOf("Inspect spark/coil", "Check injector and fuel pressure", "Check intake leaks and compression if required"),
                    listOf("Confirm the failed cylinder and measured cause before replacing parts"),
                    70
                )
                code.startsWith("P01") || code.startsWith("P02") -> DiagnosticResult(
                    "warning",
                    listOf("Sensor circuit", "Wiring/connector", "Fuel or air metering"),
                    listOf("Inspect connector and wiring", "Compare live PID against expected operating range"),
                    listOf("Repair the verified circuit or component; clear and rescan after repair"),
                    65
                )
                code.startsWith("U") -> DiagnosticResult(
                    "critical",
                    listOf("CAN communication", "Power/ground supply", "Network module fault"),
                    listOf("Check battery voltage and grounds", "Inspect CAN wiring and connector integrity", "Identify offline ECU"),
                    listOf("Do not replace an ECU until power, ground and network integrity are verified"),
                    60
                )
                code.startsWith("B") || code.startsWith("C") -> DiagnosticResult(
                    "warning",
                    listOf("Body/chassis module circuit", "Sensor or actuator", "Wiring/connector"),
                    listOf("Inspect related connector and wiring", "Check module power/ground and relevant live data"),
                    listOf("Repair only after confirming the circuit or component fault"),
                    60
                )
                else -> DiagnosticResult(
                    "info",
                    listOf("Refer to vehicle-specific DTC definition"),
                    listOf("Verify DTC applicability for the selected vehicle and ECU"),
                    listOf("Use vehicle-specific service information before replacing parts"),
                    50
                )
            }
            DiagnosticFinding(
                code = code,
                severity = severity,
                score = score,
                confidence = score / 100.0,
                causes = causes,
                tests = tests,
                recommendations = recommendations
            )
        }

    fun evaluate(
        knowledge: DtcKnowledge,
        observedSymptoms: Set<String> = emptySet(),
        liveData: List<LivePidValue> = emptyList(),
        testResults: Map<String, Boolean> = emptyMap()
    ): DiagnosticFinding {
        var score = 40
        score += observedSymptoms.count { symptom -> knowledge.symptoms.any { it.equals(symptom, true) } } * 10
        score += testResults.values.count { it } * 8
        score += liveData.count { value ->
            value.value.isFinite() && value.value in
                (value.min ?: Double.NEGATIVE_INFINITY)..(value.max ?: Double.POSITIVE_INFINITY)
        } * 2
        val bounded = score.coerceIn(0, 100)
        return DiagnosticFinding(
            code = knowledge.code,
            severity = knowledge.severity,
            score = bounded,
            confidence = bounded / 100.0,
            causes = knowledge.causes,
            tests = knowledge.tests,
            recommendations = knowledge.repairs
        )
    }

    private data class DiagnosticResult(
        val severity: String,
        val causes: List<String>,
        val tests: List<String>,
        val recommendations: List<String>,
        val score: Int
    )
}
package dz.cardiag.app.core

/** Lightweight value type for the Home "Diagnostic Health" indicator. */
data class VehicleHealthSnapshot(
    val score: Int,
    val summary: String
)

data class VehicleHealth(
    val overall: Int,
    val engine: Int,
    val transmission: Int,
    val emissions: Int,
    val electrical: Int,
    val obd: Int,
    val reasons: List<String>
)

/**
 * Deterministic vehicle health scoring. The score is intentionally derived
 * only from the actual recorded evidence; the resulting snapshot is the
 * single source of truth for the Home "Diagnostic Health" indicator.
 */
object VehicleHealthEngine {
    fun score(
        dtcCount: Int,
        pendingCount: Int,
        permanentCount: Int,
        rpm: Double?,
        coolant: Double?,
        batteryVoltage: Double?,
        readinessReady: Boolean?,
        milOn: Boolean?
    ): VehicleHealth {
        val reasons = mutableListOf<String>()
        var obd = 100 - dtcCount * 12 - pendingCount * 6 - permanentCount * 10
        if (milOn == true) obd -= 8
        obd = obd.coerceIn(0, 100)
        var engine = 100 - dtcCount * 10
        rpm?.let { if (it < 500 || it > 5000) engine -= 12 }
        coolant?.let { if (it < 60 || it > 115) engine -= 8 }
        engine = engine.coerceIn(0, 100)
        var emissions = 100 - dtcCount * 7
        if (readinessReady == false) emissions -= 15
        emissions = emissions.coerceIn(0, 100)
        var electrical = 100
        if (batteryVoltage != null && (batteryVoltage < 11.8 || batteryVoltage > 15.0)) {
            electrical -= 25
            reasons += "Battery/charging voltage is outside the expected diagnostic range."
        }
        electrical = electrical.coerceIn(0, 100)
        val transmission = 100
        if (dtcCount > 0) reasons += "$dtcCount confirmed DTC(s) affect the health score."
        if (permanentCount > 0) reasons += "$permanentCount permanent DTC(s) require follow-up."
        if (readinessReady == false) reasons += "Readiness monitors are not all ready."
        val overall = (engine * 35 + obd * 25 + emissions * 20 + electrical * 15 + transmission * 5) / 100
        return VehicleHealth(overall, engine, transmission, emissions, electrical, obd, reasons.distinct())
    }

    /**
     * Convenience snapshot for the Home screen. Without recorded evidence
     * the snapshot is null and the UI must render the "Unavailable" state.
     */
    fun snapshot(
        dtcCount: Int = 0,
        pendingCount: Int = 0,
        permanentCount: Int = 0,
        rpm: Double? = null,
        coolant: Double? = null,
        batteryVoltage: Double? = null,
        readinessReady: Boolean? = null,
        milOn: Boolean? = null
    ): VehicleHealthSnapshot? {
        if (dtcCount == 0 && pendingCount == 0 && permanentCount == 0 && rpm == null && coolant == null && batteryVoltage == null && readinessReady == null && milOn == null) {
            return null
        }
        val v = score(dtcCount, pendingCount, permanentCount, rpm, coolant, batteryVoltage, readinessReady, milOn)
        val summary = if (v.reasons.isEmpty()) "Score based on available evidence." else v.reasons.joinToString(" ")
        return VehicleHealthSnapshot(v.overall, summary)
    }
}
