internal const val KEY_ONBOARDING_DONE = "onboarding_done"
internal const val KEY_ACTIVE_VEHICLE_ID = "active_vehicle_id"
internal const val KEY_ACTIVE_VEHICLE_NAME = "active_vehicle_name"
